from pathlib import Path
root=Path(__file__).resolve().parents[1]
html=(root/'index.html').read_text().replace('<head>','<head><base href="'+root.as_uri()+'/">')
qa=r'''<script>
window.addEventListener('load',()=>{const failures=[],checks=[];const check=(ok,s)=>(ok?checks:failures).push(s);try{
setLocale('en');pool=new Set();params={...DEFAULTS};add(['points']);applyLocalization();check(!pool.has('tapir')&&!pool.has('cotracker'),'alternative is not silently selected');check(!$('drawer').hidden&&$('drawerBody').querySelector('[data-add="cotracker"]'),'alternative choice button');$('drawerBody').querySelector('[data-add="cotracker"]').click();check(pool.has('cotracker')&&!pool.has('tapir'),'choose only CoTracker');closeDrawer();remove('cotracker');check(!evaluation.winner&&!$('drawer').hidden,'removal explains broken dependency');closeDrawer();add(['rag']);check(pool.has('llm'),'RAG binds LLM');applyLocalization();check(!/[\u3400-\u9fff]/.test($('drawerBody').innerText),'binding English');
showQualcomm();check(document.querySelector('[data-qbench="precision"]').value==='FP32','FP32 default');const set=(id,value)=>{const n=document.querySelector(`[data-qbench="${id}"]`);n.value=value;n.dispatchEvent(new Event('input'));};set('ms',20);set('overhead',5);set('hz',30);set('streams',2);check($('qbenchResult').innerText.includes('40.0 FPS')&&$('qbenchResult').innerText.includes('1500.0'),'FPS and shared serial budget');check($('qbenchResult').innerText.includes('exceeded'),'overload visible');set('board','QCS8550 (Proxy)');check($('qbenchResult').innerText.includes('Proxy ≠'),'proxy disclosed');const before=JSON.stringify(params);setLocale('zh');check(document.querySelector('[data-qbench="ms"]').value==='20','language preserves worksheet');setLocale('en');check(!/[\u3400-\u9fff]/.test($('drawerBody').innerText),'worksheet English');check(JSON.stringify(params)===before,'worksheet does not replace device profiles');set('ms','');check($('qbenchResult').innerText.includes('Awaiting'),'unknown not zero or pass');closeDrawer();check(document.querySelectorAll('.section-head .step').length===0,'no numeric section markers');check(getComputedStyle(document.querySelector('.selection-flow i'),'::after').animationIterationCount==='3','finite motion');
check(document.documentElement.scrollWidth<=innerWidth,'no horizontal overflow');
const preset=$('preset');preset.value='iotlan';preset.dispatchEvent(new Event('change',{bubbles:true}));check(pool.has('iotlink')&&pool.has('llm')&&evaluation.aiot.endpoints.length>0,'AIoT preset selects endpoint plus host');
}catch(e){failures.push(e.stack);}localizationObserver?.disconnect();document.head.innerHTML='';document.body.innerHTML='<pre id="qa"></pre>';document.getElementById('qa').textContent=JSON.stringify({checks:checks.length,failures});});</script>'''
Path('/tmp/edge-guidance-qa.html').write_text(html.replace('</body>',qa+'</body>'))
